// Verus program: swap first and last elements of a non-empty Vec<i32>.
#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
    requires
        a.len() > 0,
    ensures
        result.len() == a.len(),
        // Interior elements unchanged
        forall|i: int| 1 <= i && i < a.len() as int - 1 ==> result[i] == a[i],
        // First becomes old last
        result[0] == a[a.len() as int - 1],
        // Last becomes old first
        result[a.len() as int - 1] == a[0],
{
    let n: usize = a.len();
    let mut result = a.clone();

    if n > 1 {
        // Swap in place on the cloned vector.
        let tmp = result[0];
        result.set(0, result[n - 1]);
        result.set(n - 1, tmp);
    }

    result
}

} // verus!